INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4745032', 'Siege of Toma', 'The siege of Toma was a bloodless action during the First World War on the island of New Pomerania (now New Britain) between 14 and 17 September 1914 as part of the occupation of German New Guinea by the Australian Naval and Military Expeditionary Force (AN&MEF). Australian forces had been dispatched to seize and destroy German wireless stations in the south-west Pacific because they were used by the German East Asian Cruiser Squadron of Vice Admiral Maximilian von Spee which threatened merchant shipping in the region.', 1914, 9, 14, 1914, 9, 17, 'day', '14 September 1914 – 17 September 1914', 39, 'https://en.wikipedia.org/wiki/Siege_of_Toma'),
  ('Q113621', 'Battle of Milne Bay', 'The Battle of Milne Bay (25 August – 7 September 1942), also known as Operation RE or the Battle of Rabi (ラビの戦い) by the Japanese, was a battle of the Pacific campaign of World War II. Japanese naval infantry, known as Kaigun Tokubetsu Rikusentai (Special Naval Landing Forces), with two small tanks attacked the Allied airfields at Milne Bay that had been established on the eastern tip of New Guinea. Due to poor intelligence work, the Japanese miscalculated the size of the predominantly Australian garrison and, believing that the airfields were defended by only two or three companies,…', 1942, 8, 25, 1942, 9, 7, 'day', '25 August 1942 – 7 September 1942', 57, 'https://en.wikipedia.org/wiki/Battle_of_Milne_Bay'),
  ('Q1572785', 'Battle of Rabaul', 'The Battle of Rabaul, also known by the Japanese as Operation R, an instigating action of the New Guinea campaign, was fought on the island of New Britain in the Australian Territory of New Guinea, from 23 January into February 1942. It was a strategically significant defeat of Allied forces by Japan in the Pacific campaign of World War II, with the Japanese invasion force quickly overwhelming the small Australian garrison, the majority of which was either killed or captured.', 1942, NULL, NULL, 1942, 2, NULL, 'year', '1942', 57, 'https://en.wikipedia.org/wiki/Battle_of_Rabaul_(1942)'),
  ('Q2917077', 'Battle of Buna–Gona', 'The battle of Buna–Gona was part of the New Guinea campaign in the Pacific theatre during World War II. It followed the conclusion of the Kokoda Track campaign and lasted from 16 November 1942 until 22 January 1943. The battle was fought by Australian and United States forces against the Japanese beachheads at Buna, Sanananda and Gona.', 1942, 11, 16, 1943, 1, 22, 'day', '16 November 1942 – 22 January 1943', 53, 'https://en.wikipedia.org/wiki/Battle_of_Buna%E2%80%93Gona'),
  ('Q700530', 'Battle of Cape St. George', 'The Battle of Cape St. George was a naval battle of the Pacific campaign of World War II fought on 25 November 1943, between Cape St.', 1943, 11, 25, NULL, NULL, NULL, 'day', '25 November 1943', 56, 'https://en.wikipedia.org/wiki/Battle_of_Cape_St._George'),
  ('Q704785', 'Bougainville Campaign', 'The Bougainville campaign was a series of land and naval battles of the Pacific campaign of World War II between Allied forces and the Empire of Japan, named after the island of Bougainville, one of the Solomon Islands. It was part of Operation Cartwheel, the Allied grand strategy in the South Pacific.', 1943, 11, 1, 1945, 8, 21, 'day', '1 November 1943 – 21 August 1945', 57, 'https://en.wikipedia.org/wiki/Bougainville_campaign'),
  ('Q743889', 'Battle of Wau', 'The Battle of Wau (29 January – 4 February 1943) was a battle in the New Guinea campaign of World War II. Forces of the Empire of Japan sailed from Rabaul and crossed the Solomon Sea and, despite Allied air attacks, successfully reached Lae, where they disembarked. Japanese troops then advanced overland on Wau, an Australian base that potentially threatened the Japanese positions at Salamaua and Lae.', 1943, 2, 4, 1943, 1, 31, 'day', '4 February 1943 – 31 January 1943', 48, 'https://en.wikipedia.org/wiki/Battle_of_Wau'),
  ('Q1726931', 'Operation Dexterity', 'Operation Dexterity was a military operation, part of Operation Cartwheel in the South West Pacific Area (SWPA) for the Allies in the Pacific theater of World War II. The operation was directed by the Supreme Allied Commander in the SWPA, General Douglas MacArthur. Dexterity included amphibious landings at Arawe on 15 December 1943, and Cape Gloucester on 26 December 1943 in the northwest of New Britain, the capture of the Imperial Japanese held Tuluvu aerodrome on the 30 December 1943 and the amphibious landing at Saidor on 2 January 1944.', 1943, 12, 15, 1944, 4, 22, 'day', '15 December 1943 – 22 April 1944', 34, 'https://en.wikipedia.org/wiki/Operation_Dexterity'),
  ('Q2165486', 'Battle of Empress Augusta Bay', 'The Battle of Empress Augusta Bay, on 1–2 November 1943, also known as the Battle of Gazelle Bay, Operation Cherry Blossom, and in Japanese sources as the Sea Battle off Bougainville Island (ブーゲンビル島沖海戦), was a naval battle fought at night in Empress Augusta Bay near Bougainville Island. The naval battle was a result of Allied landings at Cape Torokina in the first action in the Bougainville campaign of World War II. It is also considered part of the Solomons and New Guinea campaigns.', 1943, 11, 1, 1943, 11, 2, 'day', '1 November 1943 – 2 November 1943', 50, 'https://en.wikipedia.org/wiki/Battle_of_Empress_Augusta_Bay'),
  ('Q3293566', 'Battle of Cape Gloucester', 'The Battle of Cape Gloucester was fought in the Pacific theater of World War II between Japanese and Allied forces on the island of New Britain, Territory of New Guinea, between 26 December 1943 and 16 January 1944. Codenamed Operation Backhander, the US landing formed part of the wider Operation Cartwheel, the main Allied strategy in the South West Pacific Area and Pacific Ocean Areas during 1943–1944.', 1943, 12, 26, 1944, 4, 22, 'day', '26 December 1943 – 22 April 1944', 51, 'https://en.wikipedia.org/wiki/Battle_of_Cape_Gloucester'),
  ('Q3636298', 'Battle of Koromokina Lagoon', 'The Battle of Koromokina Lagoon was fought between the United States Marine Corps and Imperial Japanese Army forces on Bougainville Island. It took place on 7–8 November 1943 during the Bougainville campaign of the Pacific War.', 1943, 11, 7, 1943, 11, 8, 'day', '7 November 1943 – 8 November 1943', 34, 'https://en.wikipedia.org/wiki/Battle_of_Koromokina_Lagoon'),
  ('Q3951255', 'Landings at Cape Torokina', 'The Landings at Cape Torokina (1–3 November 1943), also known as Operation Cherryblossom, took place at the beginning of the Bougainville campaign in World War II. The amphibious landings were carried out by elements of the United States Marine Corps in November 1943 on Bougainville Island in the South Pacific, as part of Allied efforts to advance towards the main Japanese base around Rabaul under Operation Cartwheel. Coming in the wake of Allied successes at Guadalcanal and in the central Solomons, the landings were intended to secure a beachhead with the purpose of establishing several…', 1943, 11, 3, NULL, NULL, NULL, 'day', '3 November 1943', 37, 'https://en.wikipedia.org/wiki/Landings_at_Cape_Torokina'),
  ('Q4871014', 'Battle of Finschhafen', 'The Battle of Finschhafen was part of the Huon Peninsula campaign in New Guinea during World War II and was fought between Australian and Japanese forces. The fighting took place between 22 September and 24 October 1943 following the landing at Scarlet Beach, which was followed by a two-pronged advance on Finschhafen as the Australian 20th Infantry Brigade advanced on the town from the north, while the 22nd Infantry Battalion drove from the south, having advanced from the landing beaches east of Lae.', 1943, 9, 22, 1943, 10, 24, 'day', '22 September 1943 – 24 October 1943', 34, 'https://en.wikipedia.org/wiki/Battle_of_Finschhafen'),
  ('Q4871367', 'Battle of Kaiapit', 'The Battle of Kaiapit was an action fought in 1943 between Australian and Japanese forces in New Guinea during the Markham and Ramu Valley – Finisterre Range campaign of World War II. Following the landings at Nadzab and at Lae, the Allies attempted to exploit their success with an advance into the upper Markham Valley, starting with Kaiapit. The Japanese intended to use Kaiapit to threaten the Allied position at Nadzab, and to create a diversion to allow the Japanese garrison at Lae time to escape.', 1943, 9, 19, 1943, 9, 20, 'day', '19 September 1943 – 20 September 1943', 34, 'https://en.wikipedia.org/wiki/Battle_of_Kaiapit'),
  ('Q6484626', 'Landing at Nadzab', 'The Landing at Nadzab was an airborne landing on 5 September 1943 during the New Guinea campaign of World War II in conjunction with the landing at Lae. The Nadzab action began with a parachute drop at Lae Nadzab Airport, combined with an overland force.', 1943, 9, 5, NULL, NULL, NULL, 'day', '5 September 1943', 43, 'https://en.wikipedia.org/wiki/Landing_at_Nadzab'),
  ('Q4870924', 'Battle of Driniumor River', 'The Battle of Driniumor River, also known as the Battle of Aitape, 10 July – 25 August 1944, was part of the Western New Guinea campaign of World War II. During the fighting, Japanese forces launched several attacks on United States forces on the Driniumor River, near Aitape in New Guinea, over the course of several weeks with the intention of retaking Aitape. After making some initial gains, the Japanese attack was contained and eventually turned back having suffered heavy casualties.', 1944, 7, 10, 1944, 8, 25, 'day', '10 July 1944 – 25 August 1944', 39, 'https://en.wikipedia.org/wiki/Battle_of_Driniumor_River'),
  ('Q15914063', 'Aitape–Wewak campaign', 'The Aitape–Wewak campaign was one of the final campaigns of the Pacific Theatre of World War II. Between November 1944 and the end of the war in August 1945, the Australian 6th Division, with air and naval support, fought the Imperial Japanese 18th Army in northern New Guinea. Considered a "mopping up" operation by the Australians, and although ultimately successful for them with the Japanese forces cleared from the coastal areas and driven inland, amidst difficult jungle conditions, casualties from combat and disease were high.', 1944, 11, NULL, 1945, 8, NULL, 'month', 'November 1944 – August 1945', 43, 'https://en.wikipedia.org/wiki/Aitape%E2%80%93Wewak_campaign'),
  ('Q10360270', 'Bougainville conflict', 'The Bougainville conflict, also known as the Bougainvillean Civil War, the Solomon Civil War or the Civil War of the North Solomons was a multi-layered armed conflict fought from 1988 to 1998 in the North Solomons Province of Papua New Guinea between the governments of Papua New Guinea, supported by Australia and Indonesia and the secessionist forces of the Bougainville Revolutionary Army (BRA), the rest of the Solomon Islands and allegedly Fiji, and between the BRA and other armed groups on Bougainville. The conflict was described by Bougainvillean President John Momis as the largest…', 1988, 12, 1, 1998, 4, 20, 'day', '1 December 1988 – 20 April 1998', 51, 'https://en.wikipedia.org/wiki/Bougainville_conflict'),
  ('Q3133143', '1998 Papua New Guinea earthquake', 'The 1998 Papua New Guinea earthquake occurred on July 17 with a moment magnitude of 7.0 and a maximum Mercalli intensity of VIII (Severe). The event occurred on a reverse fault near the north coast region of Papua New Guinea, 25 km (16 mi) from the coast near Aitape and caused a large submarine landslide which caused a tsunami that hit the coast, killing between at least 2,183 and 2,700 people and injuring thousands.', 1998, 7, 17, NULL, NULL, NULL, 'day', '17 July 1998', 45, 'https://en.wikipedia.org/wiki/1998_Papua_New_Guinea_earthquake'),
  ('Q3501432', 'Airlines PNG Flight 1600', 'On 13 October 2011, Airlines PNG Flight 1600, a Dash 8 regional aircraft on a domestic flight from Lae to Madang, Papua New Guinea, crash-landed in a forested area near the mouth of the Guabe River, after losing all engine power. Only 4 of the 32 people on board survived.', 2011, 10, 13, NULL, NULL, NULL, 'day', '13 October 2011', 50, 'https://en.wikipedia.org/wiki/Airlines_PNG_Flight_1600'),
  ('Q50178713', '2018 Papua New Guinea earthquake', 'The Papua New Guinea earthquake was a magnitude 7.5 earthquake that occurred in the Hela Province of Papua New Guinea on 26 February 2018 (25 February UTC), at 3:44 a.m. local time (25 February, 17:44 UTC).', 2018, 2, 25, NULL, NULL, NULL, 'day', '25 February 2018', 56, 'https://en.wikipedia.org/wiki/2018_Papua_New_Guinea_earthquake'),
  ('Q113900838', '2022 Papua New Guinea earthquake', 'On 11 September 2022, an earthquake of moment magnitude 7.6–7.7 struck Papua New Guinea, in the northern part of Morobe Province. The normal faulting earthquake occurred with a hypocenter depth of 116.0 km (72.1 mi) beneath the Finisterre Range.', 2022, 9, 11, NULL, NULL, NULL, 'day', '11 September 2022', 61, 'https://en.wikipedia.org/wiki/2022_Papua_New_Guinea_earthquake'),
  ('Q117424624', '2023 Papua New Guinea earthquake', 'A magnitude 7.1 earthquake struck 38.3 km (23.8 mi) east-southeast of Ambunti in East Sepik Province, Papua New Guinea on 3 April 2023.', 2023, 4, 3, NULL, NULL, NULL, 'day', '3 April 2023', 39, 'https://en.wikipedia.org/wiki/2023_Papua_New_Guinea_earthquake'),
  ('Q125150843', '2024 East Sepik earthquake', 'On 24 March 2024, a Mw 6.9 earthquake occurred in the East Sepik Province of Papua New Guinea, killing five people.', 2024, 3, 24, NULL, NULL, NULL, 'day', '24 March 2024', 34, 'https://en.wikipedia.org/wiki/2024_East_Sepik_earthquake');
